    33→
    34→const (
    35→	// BlobSidecarVersion0 includes a single proof for verifying the entire blob
    36→	// against its commitment. Used when the full blob is available and needs to
    37→	// be checked as a whole.
    38→	BlobSidecarVersion0 = byte(0)
    39→
    40→	// BlobSidecarVersion1 includes multiple cell proofs for verifying specific
    41→	// blob elements (cells). Used in scenarios like data availability sampling,
    42→	// where only portions of the blob are verified individually.
    43→	BlobSidecarVersion1 = byte(1)
    44→)
    45→
    46→// BlobTx represents an EIP-4844 transaction.
    47→type BlobTx struct {
    48→	ChainID    *uint256.Int
    49→	Nonce      uint64
    50→	GasTipCap  *uint256.Int // a.k.a. maxPriorityFeePerGas
    51→	GasFeeCap  *uint256.Int // a.k.a. maxFeePerGas
    52→	Gas        uint64
    53→	To         common.Address
    54→	Value      *uint256.Int
    55→	Data       []byte
    56→	AccessList AccessList
    57→	BlobFeeCap *uint256.Int // a.k.a. maxFeePerBlobGas
    58→	BlobHashes []common.Hash
    59→
    60→	// A blob transaction can optionally contain blobs. This field must be set when BlobTx
    61→	// is used to create a transaction for signing.
    62→	Sidecar *BlobTxSidecar `rlp:"-"`
    63→
    64→	// Signature values
    65→	V *uint256.Int
    66→	R *uint256.Int
    67→	S *uint256.Int
    68→}
    69→
    70→// BlobTxSidecar contains the blobs of a blob transaction.
    71→type BlobTxSidecar struct {
    72→	Version     byte                 // Version
    73→	Blobs       []kzg4844.Blob       // Blobs needed by the blob pool
    74→	Commitments []kzg4844.Commitment // Commitments needed by the blob pool
    75→	Proofs      []kzg4844.Proof      // Proofs needed by the blob pool
    76→}
    77→
    78→// NewBlobTxSidecar initialises the BlobTxSidecar object with the provided parameters.
    79→func NewBlobTxSidecar(version byte, blobs []kzg4844.Blob, commitments []kzg4844.Commitment, proofs []kzg4844.Proof) *BlobTxSidecar {
    80→	return &BlobTxSidecar{
    81→		Version:     version,
    82→		Blobs:       blobs,
    83→		Commitments: commitments,
    84→		Proofs:      proofs,
    85→	}
    86→}
    87→
    88→// BlobHashes computes the blob hashes of the given blobs.
    89→func (sc *BlobTxSidecar) BlobHashes() []common.Hash {
    90→	hasher := sha256.New()
    91→	h := make([]common.Hash, len(sc.Commitments))
    92→	for i := range sc.Blobs {
    93→		h[i] = kzg4844.CalcBlobHashV1(hasher, &sc.Commitments[i])
    94→	}
    95→	return h
    96→}
    97→
    98→// CellProofsAt returns the cell proofs for blob with index idx.
    99→// This method is only valid for sidecars with version 1.
   100→func (sc *BlobTxSidecar) CellProofsAt(idx int) ([]kzg4844.Proof, error) {
   101→	if sc.Version != BlobSidecarVersion1 {
   102→		return nil, fmt.Errorf("cell proof unsupported, version: %d", sc.Version)
   103→	}
   104→	if idx < 0 || idx >= len(sc.Blobs) {
   105→		return nil, fmt.Errorf("cell proof out of bounds, index: %d, blobs: %d", idx, len(sc.Blobs))
   106→	}
   107→	index := idx * kzg4844.CellProofsPerBlob
   108→	if len(sc.Proofs) < index+kzg4844.CellProofsPerBlob {
   109→		return nil, fmt.Errorf("cell proof is corrupted, index: %d, proofs: %d", idx, len(sc.Proofs))
   110→	}
   111→	return sc.Proofs[index : index+kzg4844.CellProofsPerBlob], nil
   112→}
   113→
   114→// ToV1 converts the BlobSidecar to version 1, attaching the cell proofs.
   115→func (sc *BlobTxSidecar) ToV1() error {
   116→	if sc.Version == BlobSidecarVersion1 {
   117→		return nil
   118→	}
   119→	if sc.Version == BlobSidecarVersion0 {
   120→		proofs := make([]kzg4844.Proof, 0, len(sc.Blobs)*kzg4844.CellProofsPerBlob)
   121→		for _, blob := range sc.Blobs {
   122→			cellProofs, err := kzg4844.ComputeCellProofs(&blob)
   123→			if err != nil {
   124→				return err
   125→			}
   126→			proofs = append(proofs, cellProofs...)
   127→		}
   128→		sc.Version = BlobSidecarVersion1
   129→		sc.Proofs = proofs
   130→	}
   131→	return nil
   132→}
   133→
   134→// encodedSize computes the RLP size of the sidecar elements. This does NOT return the
   135→// encoded size of the BlobTxSidecar, it's just a helper for tx.Size().
   136→func (sc *BlobTxSidecar) encodedSize() uint64 {
   137→	var blobs, commitments, proofs uint64
   138→	for i := range sc.Blobs {
   139→		blobs += rlp.BytesSize(sc.Blobs[i][:])
   140→	}
   141→	for i := range sc.Commitments {
   142→		commitments += rlp.BytesSize(sc.Commitments[i][:])
   143→	}
   144→	for i := range sc.Proofs {
   145→		proofs += rlp.BytesSize(sc.Proofs[i][:])
   146→	}
   147→	return rlp.ListSize(blobs) + rlp.ListSize(commitments) + rlp.ListSize(proofs)
   148→}
   149→
   150→// ValidateBlobCommitmentHashes checks whether the given hashes correspond to the
   151→// commitments in the sidecar
   152→func (sc *BlobTxSidecar) ValidateBlobCommitmentHashes(hashes []common.Hash) error {
   153→	if len(sc.Commitments) != len(hashes) {
   154→		return fmt.Errorf("invalid number of %d blob commitments compared to %d blob hashes", len(sc.Commitments), len(hashes))
   155→	}
   156→	hasher := sha256.New()
   157→	for i, vhash := range hashes {
   158→		computed := kzg4844.CalcBlobHashV1(hasher, &sc.Commitments[i])
   159→		if vhash != computed {
   160→			return fmt.Errorf("blob %d: computed hash %#x mismatches transaction one %#x", i, computed, vhash)
   161→		}
   162→	}
   163→	return nil
   164→}
   165→
   166→// Copy returns a deep-copied BlobTxSidecar object.
   167→func (sc *BlobTxSidecar) Copy() *BlobTxSidecar {
   168→	return &BlobTxSidecar{
   169→		Version: sc.Version,
   170→
   171→		// The element of these slice is fix-size byte array,
   172→		// therefore slices.Clone will actually deep copy by value.
   173→		Blobs:       slices.Clone(sc.Blobs),
   174→		Commitments: slices.Clone(sc.Commitments),
   175→		Proofs:      slices.Clone(sc.Proofs),
   176→	}
   177→}
   178→
   179→// blobTxWithBlobs represents blob tx with its corresponding sidecar.
   180→// This is an interface because sidecars are versioned.
   181→type blobTxWithBlobs interface {
   182→	tx() *BlobTx
   183→	assign(*BlobTxSidecar) error
   184→}
   185→
   186→type blobTxWithBlobsV0 struct {
   187→	BlobTx      *BlobTx
   188→	Blobs       []kzg4844.Blob
   189→	Commitments []kzg4844.Commitment
   190→	Proofs      []kzg4844.Proof
   191→}
   192→
   193→type blobTxWithBlobsV1 struct {
   194→	BlobTx      *BlobTx
   195→	Version     byte
   196→	Blobs       []kzg4844.Blob
   197→	Commitments []kzg4844.Commitment
   198→	Proofs      []kzg4844.Proof
   199→}
   200→
   201→func (btx *blobTxWithBlobsV0) tx() *BlobTx {
   202→	return btx.BlobTx
   203→}
   204→
   205→func (btx *blobTxWithBlobsV0) assign(sc *BlobTxSidecar) error {
   206→	sc.Version = BlobSidecarVersion0
   207→	sc.Blobs = btx.Blobs
   208→	sc.Commitments = btx.Commitments
   209→	sc.Proofs = btx.Proofs
   210→	return nil
   211→}
   212→
   213→func (btx *blobTxWithBlobsV1) tx() *BlobTx {
   214→	return btx.BlobTx
   215→}
   216→
   217→func (btx *blobTxWithBlobsV1) assign(sc *BlobTxSidecar) error {
   218→	if btx.Version != BlobSidecarVersion1 {
   219→		return fmt.Errorf("unsupported blob tx version %d", btx.Version)
   220→	}
   221→	sc.Version = BlobSidecarVersion1
   222→	sc.Blobs = btx.Blobs
   223→	sc.Commitments = btx.Commitments
   224→	sc.Proofs = btx.Proofs
   225→	return nil
   226→}
   227→
   228→// copy creates a deep copy of the transaction data and initializes all fields.
   229→func (tx *BlobTx) copy() TxData {
   230→	cpy := &BlobTx{
   231→		Nonce: tx.Nonce,
   232→		To:    tx.To,
   233→		Data:  common.CopyBytes(tx.Data),
   234→		Gas:   tx.Gas,
   235→		// These are copied below.
   236→		AccessList: make(AccessList, len(tx.AccessList)),
   237→		BlobHashes: make([]common.Hash, len(tx.BlobHashes)),
   238→		Value:      new(uint256.Int),
   239→		ChainID:    new(uint256.Int),
   240→		GasTipCap:  new(uint256.Int),
   241→		GasFeeCap:  new(uint256.Int),
   242→		BlobFeeCap: new(uint256.Int),
   243→		V:          new(uint256.Int),
   244→		R:          new(uint256.Int),
   245→		S:          new(uint256.Int),
   246→	}
   247→	copy(cpy.AccessList, tx.AccessList)
   248→	copy(cpy.BlobHashes, tx.BlobHashes)
   249→
   250→	if tx.Value != nil {
   251→		cpy.Value.Set(tx.Value)
   252→	}
   253→	if tx.ChainID != nil {
   254→		cpy.ChainID.Set(tx.ChainID)
   255→	}
   256→	if tx.GasTipCap != nil {
   257→		cpy.GasTipCap.Set(tx.GasTipCap)
   258→	}
   259→	if tx.GasFeeCap != nil {
   260→		cpy.GasFeeCap.Set(tx.GasFeeCap)
   261→	}
   262→	if tx.BlobFeeCap != nil {
   263→		cpy.BlobFeeCap.Set(tx.BlobFeeCap)
   264→	}
   265→	if tx.V != nil {
   266→		cpy.V.Set(tx.V)
   267→	}
   268→	if tx.R != nil {
   269→		cpy.R.Set(tx.R)
   270→	}
   271→	if tx.S != nil {
   272→		cpy.S.Set(tx.S)
   273→	}
   274→	if tx.Sidecar != nil {
   275→		cpy.Sidecar = tx.Sidecar.Copy()
   276→	}
   277→	return cpy
   278→}
