   280→// accessors for innerTx.
   281→func (tx *BlobTx) txType() byte           { return BlobTxType }
   282→func (tx *BlobTx) chainID() *big.Int      { return tx.ChainID.ToBig() }
   283→func (tx *BlobTx) accessList() AccessList { return tx.AccessList }
   284→func (tx *BlobTx) data() []byte           { return tx.Data }
