   287→func (tx *BlobTx) gasTipCap() *big.Int    { return tx.GasTipCap.ToBig() }
   288→func (tx *BlobTx) gasPrice() *big.Int     { return tx.GasFeeCap.ToBig() }
   289→func (tx *BlobTx) value() *big.Int        { return tx.Value.ToBig() }
   290→func (tx *BlobTx) nonce() uint64          { return tx.Nonce }
   291→func (tx *BlobTx) to() *common.Address    { tmp := tx.To; return &tmp }
   292→func (tx *BlobTx) blobGas() uint64        { return params.BlobTxBlobGasPerBlob * uint64(len(tx.BlobHashes)) }
   293→
   294→func (tx *BlobTx) effectiveGasPrice(dst *big.Int, baseFee *big.Int) *big.Int {
   295→	if baseFee == nil {
   296→		return dst.Set(tx.GasFeeCap.ToBig())
   297→	}
   298→	tip := dst.Sub(tx.GasFeeCap.ToBig(), baseFee)
   299→	if tip.Cmp(tx.GasTipCap.ToBig()) > 0 {
   300→		tip.Set(tx.GasTipCap.ToBig())
   301→	}
   302→	return tip.Add(tip, baseFee)
   303→}
   304→
   305→func (tx *BlobTx) rawSignatureValues() (v, r, s *big.Int) {
   306→	return tx.V.ToBig(), tx.R.ToBig(), tx.S.ToBig()
   307→}
   308→
   309→func (tx *BlobTx) setSignatureValues(chainID, v, r, s *big.Int) {
   310→	tx.ChainID.SetFromBig(chainID)
   311→	tx.V.SetFromBig(v)
   312→	tx.R.SetFromBig(r)
   313→	tx.S.SetFromBig(s)
   314→}
   315→
   316→func (tx *BlobTx) withoutSidecar() *BlobTx {
   317→	cpy := *tx
   318→	cpy.Sidecar = nil
   319→	return &cpy
   320→}
   321→
   322→func (tx *BlobTx) withSidecar(sideCar *BlobTxSidecar) *BlobTx {
   323→	cpy := *tx
   324→	cpy.Sidecar = sideCar
   325→	return &cpy
   326→}
   327→
   328→func (tx *BlobTx) encode(b *bytes.Buffer) error {
   329→	switch {
   330→	case tx.Sidecar == nil:
   331→		return rlp.Encode(b, tx)
   332→
   333→	case tx.Sidecar.Version == BlobSidecarVersion0:
   334→		return rlp.Encode(b, &blobTxWithBlobsV0{
   335→			BlobTx:      tx,
   336→			Blobs:       tx.Sidecar.Blobs,
   337→			Commitments: tx.Sidecar.Commitments,
   338→			Proofs:      tx.Sidecar.Proofs,
   339→		})
   340→
   341→	case tx.Sidecar.Version == BlobSidecarVersion1:
   342→		return rlp.Encode(b, &blobTxWithBlobsV1{
   343→			BlobTx:      tx,
   344→			Version:     tx.Sidecar.Version,
   345→			Blobs:       tx.Sidecar.Blobs,
   346→			Commitments: tx.Sidecar.Commitments,
   347→			Proofs:      tx.Sidecar.Proofs,
   348→		})
   349→
   350→	default:
   351→		return errors.New("unsupported sidecar version")
   352→	}
   353→}
   354→
   355→func (tx *BlobTx) decode(input []byte) error {
   356→	// Here we need to support two outer formats: the network protocol encoding of the tx
   357→	// (with blobs) or the canonical encoding without blobs.
   358→	//
   359→	// The canonical encoding is just a list of fields:
   360→	//
   361→	//     [chainID, nonce, ...]
   362→	//
   363→	// The network encoding is a list where the first element is the tx in the canonical encoding,
   364→	// and the remaining elements are the 'sidecar':
   365→	//
   366→	//     [[chainID, nonce, ...], ...]
   367→	//
   368→	// The two outer encodings can be distinguished by checking whether the first element
   369→	// of the input list is itself a list. If it's the canonical encoding, the first
   370→	// element is the chainID, which is a number.
   371→
   372→	firstElem, _, err := rlp.SplitList(input)
   373→	if err != nil {
   374→		return err
   375→	}
   376→	firstElemKind, _, secondElem, err := rlp.Split(firstElem)
   377→	if err != nil {
   378→		return err
   379→	}
   380→	if firstElemKind != rlp.List {
   381→		// Blob tx without blobs.
   382→		return rlp.DecodeBytes(input, tx)
   383→	}
   384→
   385→	// Now we know it's the network encoding with the blob sidecar. Here we again need to
   386→	// support multiple encodings: legacy sidecars (v0) with a blob proof, and versioned
   387→	// sidecars.
   388→	//
   389→	// The legacy encoding is:
   390→	//
   391→	//     [tx, blobs, commitments, proofs]
   392→	//
   393→	// The versioned encoding is:
   394→	//
   395→	//     [tx, version, blobs, ...]
   396→	//
   397→	// We can tell the two apart by checking whether the second element is the version byte.
   398→	// For legacy sidecar the second element is a list of blobs.
   399→
   400→	secondElemKind, _, _, err := rlp.Split(secondElem)
   401→	if err != nil {
   402→		return err
   403→	}
   404→	var payload blobTxWithBlobs
   405→	if secondElemKind == rlp.List {
   406→		// No version byte: blob sidecar v0.
   407→		payload = new(blobTxWithBlobsV0)
   408→	} else {
   409→		// It has a version byte. Decode as v1, version is checked by assign()
   410→		payload = new(blobTxWithBlobsV1)
   411→	}
   412→	if err := rlp.DecodeBytes(input, payload); err != nil {
   413→		return err
   414→	}
   415→	sc := new(BlobTxSidecar)
   416→	if err := payload.assign(sc); err != nil {
   417→		return err
   418→	}
   419→	*tx = *payload.tx()
   420→	tx.Sidecar = sc
   421→	return nil
   422→}
   423→
   424→func (tx *BlobTx) sigHash(chainID *big.Int) common.Hash {
   425→	return prefixedRlpHash(
   426→		BlobTxType,
   427→		[]any{
   428→			chainID,
   429→			tx.Nonce,
   430→			tx.GasTipCap,
   431→			tx.GasFeeCap,
   432→			tx.Gas,
   433→			tx.To,
   434→			tx.Value,
   435→			tx.Data,
   436→			tx.AccessList,
   437→			tx.BlobFeeCap,
   438→			tx.BlobHashes,
   439→		})
   440→}
