   207→// ForkchoiceUpdatedV3 is equivalent to V2 with the addition of parent beacon block root
   208→// in the payload attributes. It supports only PayloadAttributesV3.
   209→func (api *ConsensusAPI) ForkchoiceUpdatedV3(update engine.ForkchoiceStateV1, params *engine.PayloadAttributes) (engine.ForkChoiceResponse, error) {
   210→	if params != nil {
   211→		switch {
   212→		case params.Withdrawals == nil:
   213→			return engine.STATUS_INVALID, attributesErr("missing withdrawals")
   214→		case params.BeaconRoot == nil:
   215→			return engine.STATUS_INVALID, attributesErr("missing beacon root")
   216→		case !api.checkFork(params.Timestamp, forks.Cancun, forks.Prague, forks.Osaka, forks.BPO1, forks.BPO2, forks.BPO3, forks.BPO4, forks.BPO5):
   217→			return engine.STATUS_INVALID, unsupportedForkErr("fcuV3 must only be called for cancun/prague/osaka payloads")
   218→		}
   219→	}
   220→	// TODO(matt): the spec requires that fcu is applied when called on a valid
   221→	// hash, even if params are wrong. To do this we need to split up
   222→	// forkchoiceUpdate into a function that only updates the head and then a
   223→	// function that kicks off block construction.
   224→	return api.forkchoiceUpdated(update, params, engine.PayloadV3, false)
   225→}
   226→
   227→func (api *ConsensusAPI) forkchoiceUpdated(update engine.ForkchoiceStateV1, payloadAttributes *engine.PayloadAttributes, payloadVersion engine.PayloadVersion, payloadWitness bool) (engine.ForkChoiceResponse, error) {
   228→	api.forkchoiceLock.Lock()
   229→	defer api.forkchoiceLock.Unlock()
   230→
   231→	log.Trace("Engine API request received", "method", "ForkchoiceUpdated", "head", update.HeadBlockHash, "finalized", update.FinalizedBlockHash, "safe", update.SafeBlockHash)
   232→	if update.HeadBlockHash == (common.Hash{}) {
   233→		log.Warn("Forkchoice requested update to zero hash")
   234→		return engine.STATUS_INVALID, nil // TODO(karalabe): Why does someone send us this?
   235→	}
   236→	// Stash away the last update to warn the user if the beacon client goes offline
   237→	api.lastForkchoiceUpdate.Store(time.Now().Unix())
   238→
   239→	// Check whether we have the block yet in our database or not. If not, we'll
   240→	// need to either trigger a sync, or to reject this forkchoice update for a
   241→	// reason.
   242→	block := api.eth.BlockChain().GetBlockByHash(update.HeadBlockHash)
   243→	if block == nil {
   244→		// If this block was previously invalidated, keep rejecting it here too
   245→		if res := api.checkInvalidAncestor(update.HeadBlockHash, update.HeadBlockHash); res != nil {
   246→			return engine.ForkChoiceResponse{PayloadStatus: *res, PayloadID: nil}, nil
   247→		}
   248→		// If the head hash is unknown (was not given to us in a newPayload request),
   249→		// we cannot resolve the header, so not much to do. This could be extended in
   250→		// the future to resolve from the `eth` network, but it's an unexpected case
   251→		// that should be fixed, not papered over.
   252→		header := api.remoteBlocks.get(update.HeadBlockHash)
   253→		if header == nil {
   254→			log.Warn("Fetching the unknown forkchoice head from network", "hash", update.HeadBlockHash)
   255→			retrievedHead, err := api.eth.Downloader().GetHeader(update.HeadBlockHash)
   256→			if err != nil {
   257→				log.Warn("Could not retrieve unknown head from peers")
   258→				return engine.STATUS_SYNCING, nil
   259→			}
   260→			api.remoteBlocks.put(retrievedHead.Hash(), retrievedHead)
   261→			header = retrievedHead
   262→		}
   263→		// If the finalized hash is known, we can direct the downloader to move
   264→		// potentially more data to the freezer from the get go.
   265→		finalized := api.remoteBlocks.get(update.FinalizedBlockHash)
   266→
   267→		// Header advertised via a past newPayload request. Start syncing to it.
   268→		context := []interface{}{"number", header.Number, "hash", header.Hash()}
   269→		if update.FinalizedBlockHash != (common.Hash{}) {
   270→			if finalized == nil {
   271→				context = append(context, []interface{}{"finalized", "unknown"}...)
   272→			} else {
   273→				context = append(context, []interface{}{"finalized", finalized.Number}...)
   274→			}
