    61→func (c *ChainConfig) ForkAtEpoch(epoch uint64) Fork {
    62→	for i := len(c.Forks) - 1; i >= 0; i-- {
    63→		if c.Forks[i].Epoch <= epoch {
    64→			return *c.Forks[i]
    65→		}
    66→	}
    67→	return Fork{}
    68→}
