    37→// Handshake executes the eth protocol handshake, negotiating version number,
    38→// network IDs, difficulties, head and genesis blocks.
    39→func (p *Peer) Handshake(networkID uint64, chain *core.BlockChain, rangeMsg BlockRangeUpdatePacket) error {
    40→	switch p.version {
    41→	case ETH69:
    42→		return p.handshake69(networkID, chain, rangeMsg)
    43→	case ETH68:
    44→		return p.handshake68(networkID, chain)
    45→	default:
    46→		return errors.New("unsupported protocol version")
    47→	}
    48→}
    49→
    50→func (p *Peer) handshake68(networkID uint64, chain *core.BlockChain) error {
    51→	var (
    52→		genesis    = chain.Genesis()
    53→		latest     = chain.CurrentBlock()
    54→		forkID     = forkid.NewID(chain.Config(), genesis, latest.Number.Uint64(), latest.Time)
    55→		forkFilter = forkid.NewFilter(chain)
    56→	)
    57→	errc := make(chan error, 2)
    58→	go func() {
    59→		pkt := &StatusPacket68{
    60→			ProtocolVersion: uint32(p.version),
    61→			NetworkID:       networkID,
    62→			Head:            latest.Hash(),
    63→			Genesis:         genesis.Hash(),
    64→			ForkID:          forkID,
    65→		}
    66→		errc <- p2p.Send(p.rw, StatusMsg, pkt)
    67→	}()
    68→	var status StatusPacket68 // safe to read after two values have been received from errc
    69→	go func() {
    70→		errc <- p.readStatus68(networkID, &status, genesis.Hash(), forkFilter)
    71→	}()
    72→
    73→	return waitForHandshake(errc, p)
    74→}
    75→
    76→func (p *Peer) readStatus68(networkID uint64, status *StatusPacket68, genesis common.Hash, forkFilter forkid.Filter) error {
    77→	if err := p.readStatusMsg(status); err != nil {
    78→		return err
    79→	}
    80→	if status.NetworkID != networkID {
    81→		return fmt.Errorf("%w: %d (!= %d)", errNetworkIDMismatch, status.NetworkID, networkID)
    82→	}
    83→	if uint(status.ProtocolVersion) != p.version {
    84→		return fmt.Errorf("%w: %d (!= %d)", errProtocolVersionMismatch, status.ProtocolVersion, p.version)
    85→	}
    86→	if status.Genesis != genesis {
    87→		return fmt.Errorf("%w: %x (!= %x)", errGenesisMismatch, status.Genesis, genesis)
    88→	}
    89→	if err := forkFilter(status.ForkID); err != nil {
    90→		return fmt.Errorf("%w: %v", errForkIDRejected, err)
    91→	}
    92→	return nil
    93→}
