    95→func (p *Peer) handshake69(networkID uint64, chain *core.BlockChain, rangeMsg BlockRangeUpdatePacket) error {
    96→	var (
    97→		genesis    = chain.Genesis()
    98→		latest     = chain.CurrentBlock()
    99→		forkID     = forkid.NewID(chain.Config(), genesis, latest.Number.Uint64(), latest.Time)
   100→		forkFilter = forkid.NewFilter(chain)
   101→	)
   102→
   103→	errc := make(chan error, 2)
   104→	go func() {
   105→		pkt := &StatusPacket69{
   106→			ProtocolVersion: uint32(p.version),
   107→			NetworkID:       networkID,
   108→			Genesis:         genesis.Hash(),
   109→			ForkID:          forkID,
   110→			EarliestBlock:   rangeMsg.EarliestBlock,
   111→			LatestBlock:     rangeMsg.LatestBlock,
   112→			LatestBlockHash: rangeMsg.LatestBlockHash,
   113→		}
   114→		errc <- p2p.Send(p.rw, StatusMsg, pkt)
   115→	}()
   116→	var status StatusPacket69 // safe to read after two values have been received from errc
   117→	go func() {
   118→		errc <- p.readStatus69(networkID, &status, genesis.Hash(), forkFilter)
   119→	}()
   120→
   121→	return waitForHandshake(errc, p)
   122→}
