   124→func (p *Peer) readStatus69(networkID uint64, status *StatusPacket69, genesis common.Hash, forkFilter forkid.Filter) error {
   125→	if err := p.readStatusMsg(status); err != nil {
   126→		return err
   127→	}
   128→	if status.NetworkID != networkID {
   129→		return fmt.Errorf("%w: %d (!= %d)", errNetworkIDMismatch, status.NetworkID, networkID)
   130→	}
   131→	if uint(status.ProtocolVersion) != p.version {
   132→		return fmt.Errorf("%w: %d (!= %d)", errProtocolVersionMismatch, status.ProtocolVersion, p.version)
   133→	}
   134→	if status.Genesis != genesis {
   135→		return fmt.Errorf("%w: %x (!= %x)", errGenesisMismatch, status.Genesis, genesis)
   136→	}
   137→	if err := forkFilter(status.ForkID); err != nil {
   138→		return fmt.Errorf("%w: %v", errForkIDRejected, err)
   139→	}
   140→	// Handle initial block range.
   141→	initRange := &BlockRangeUpdatePacket{
   142→		EarliestBlock:   status.EarliestBlock,
   143→		LatestBlock:     status.LatestBlock,
   144→		LatestBlockHash: status.LatestBlockHash,
   145→	}
   146→	if err := initRange.Validate(); err != nil {
   147→		return fmt.Errorf("%w: %v", errInvalidBlockRange, err)
   148→	}
   149→	p.lastRange.Store(initRange)
   150→	return nil
   151→}
