   153→// readStatusMsg reads the first message on the connection.
   154→func (p *Peer) readStatusMsg(dst any) error {
   155→	msg, err := p.rw.ReadMsg()
   156→	if err != nil {
   157→		return err
   158→	}
   159→	if msg.Code != StatusMsg {
   160→		return fmt.Errorf("%w: first msg has code %x (!= %x)", errNoStatusMsg, msg.Code, StatusMsg)
   161→	}
   162→	if msg.Size > maxMessageSize {
   163→		return fmt.Errorf("%w: %v > %v", errMsgTooLarge, msg.Size, maxMessageSize)
   164→	}
   165→	if err := msg.Decode(dst); err != nil {
   166→		return err
   167→	}
   168→	return nil
   169→}
