   171→func waitForHandshake(errc <-chan error, p *Peer) error {
   172→	timeout := time.NewTimer(handshakeTimeout)
   173→	defer timeout.Stop()
   174→	for range 2 {
   175→		select {
   176→		case err := <-errc:
   177→			if err != nil {
   178→				markError(p, err)
   179→				return err
   180→			}
   181→		case <-timeout.C:
   182→			markError(p, p2p.DiscReadTimeout)
   183→			return p2p.DiscReadTimeout
   184→		}
   185→	}
   186→	return nil
   187→}
   188→
   189→// markError registers the error with the corresponding metric.
   190→func markError(p *Peer, err error) {
   191→	if !metrics.Enabled() {
   192→		return
   193→	}
   194→	m := meters.get(p.Inbound())
   195→	switch errors.Unwrap(err) {
   196→	case errNetworkIDMismatch:
   197→		m.networkIDMismatch.Mark(1)
   198→	case errProtocolVersionMismatch:
   199→		m.protocolVersionMismatch.Mark(1)
   200→	case errGenesisMismatch:
   201→		m.genesisMismatch.Mark(1)
   202→	case errForkIDRejected:
   203→		m.forkidRejected.Mark(1)
   204→	case p2p.DiscReadTimeout:
   205→		m.timeoutError.Mark(1)
   206→	default:
   207→		m.peerError.Mark(1)
   208→	}
   209→}
