   211→// Validate checks basic validity of a block range announcement.
   212→func (p *BlockRangeUpdatePacket) Validate() error {
   213→	if p.EarliestBlock > p.LatestBlock {
   214→		return errors.New("earliest > latest")
   215→	}
   216→	if p.LatestBlockHash == (common.Hash{}) {
   217→		return errors.New("zero latest hash")
   218→	}
   219→	return nil
   220→}
